/* AI Daily News — client. Loads news.json (regenerated by CI every 3 hours),
   renders category tabs + headline cards, and refreshes itself periodically. */

const REFRESH_INTERVAL_MS = 15 * 60 * 1000;

const state = { data: null, tab: "all" };

const $feed = document.getElementById("feed");
const $tabs = document.getElementById("tabs");
const $updated = document.getElementById("updated");
const $refresh = document.getElementById("refresh");

function relTime(iso) {
  if (!iso) return "";
  const mins = Math.round((Date.now() - new Date(iso).getTime()) / 60000);
  if (mins < 1) return "just now";
  if (mins < 60) return `${mins}m ago`;
  const hours = Math.round(mins / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.round(hours / 24)}d ago`;
}

function renderTabs() {
  const cats = [{ id: "all", name: "All" }, ...state.data.categories];
  $tabs.replaceChildren(
    ...cats.map((c) => {
      const b = document.createElement("button");
      b.className = "tab";
      b.role = "tab";
      b.textContent = c.name;
      b.setAttribute("aria-selected", String(state.tab === c.id));
      b.addEventListener("click", () => {
        state.tab = c.id;
        renderTabs();
        renderFeed();
      });
      return b;
    })
  );
}

function articleCard(a) {
  const li = document.createElement("li");
  li.className = "card";
  const link = document.createElement("a");
  link.href = a.url;
  link.target = "_blank";
  link.rel = "noopener";
  const h = document.createElement("p");
  h.className = "headline";
  h.textContent = a.title;
  const by = document.createElement("p");
  by.className = "byline";
  if (a.source) {
    const s = document.createElement("span");
    s.className = "source";
    s.textContent = a.source;
    by.append(s);
  }
  const t = document.createElement("span");
  t.textContent = relTime(a.published);
  by.append(t);
  link.append(h, by);
  li.append(link);
  return li;
}

function renderFeed() {
  const cats =
    state.tab === "all"
      ? state.data.categories
      : state.data.categories.filter((c) => c.id === state.tab);

  const frag = document.createDocumentFragment();
  for (const cat of cats) {
    if (!cat.articles.length) continue;
    if (state.tab === "all") {
      const h2 = document.createElement("h2");
      h2.className = "section-title";
      h2.textContent = cat.name;
      frag.append(h2);
    }
    const ul = document.createElement("ul");
    ul.className = "card-list";
    const items = state.tab === "all" ? cat.articles.slice(0, 5) : cat.articles;
    ul.append(...items.map(articleCard));
    frag.append(ul);
  }
  $feed.replaceChildren(frag);
  $updated.textContent = `Updated ${relTime(state.data.updated)}`;
}

async function load({ spin = false } = {}) {
  if (spin) $refresh.classList.add("spinning");
  try {
    const res = await fetch(`news.json?t=${Date.now()}`, { cache: "no-store" });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    state.data = await res.json();
    renderTabs();
    renderFeed();
  } catch (err) {
    if (!state.data) {
      document.getElementById("status").textContent =
        "Couldn't load headlines. Check your connection and pull to refresh.";
    }
    console.error("news.json load failed:", err);
  } finally {
    $refresh.classList.remove("spinning");
  }
}

$refresh.addEventListener("click", () => load({ spin: true }));
document.addEventListener("visibilitychange", () => {
  if (!document.hidden) load();
});
setInterval(load, REFRESH_INTERVAL_MS);
load();

if ("serviceWorker" in navigator) {
  navigator.serviceWorker.register("sw.js");
}
